// Client-safe product lookup used by the cart and the checkout page.
//
// Reads the slim index generated by scripts/build-product-index.mjs
// (sku, name, slug, price, image, unit, category, stock, brand, onlineSale
// [+ restriction, isFeatured]). Full product records live server-side in
// ./catalog.server.js.
//
// Products matched by app/config/sale-restrictions.js arrive here with
// onlineSale:false and stock:0; their SKUs are registered with the cart
// helpers so addToCart / setQty refuse them.
import productsData from "./products.index.json";
import { registerRestrictedSkus } from "../../lib-shop/cart";

export const products = productsData;

// Fast lookup by SKU (used as the stable cart key).
export const productBySku = Object.fromEntries(products.map((p) => [p.sku, p]));

export const restrictedSkus = products.filter((p) => p.onlineSale === false).map((p) => p.sku);
registerRestrictedSkus(restrictedSkus);

export const isNotForOnlineSale = (product) => Boolean(product) && product.onlineSale === false;

export function getProduct(sku) {
  return productBySku[sku];
}

// Gallery "views" -> level-1 catalogue category. The old four crop-protection
// views keep resolving to the category that now holds those products.
const VIEW_TO_CATEGORY = {
  Seeds: "Seeds",
  "Crop Protection": "Crop Protection",
  "Crop Nutrition": "Crop Nutrition",
  "Farm Machinery": "Farm Machinery",
  "Animal Husbandry": "Animal Husbandry",
  Insecticide: "Crop Protection",
  Insecticides: "Crop Protection",
  Herbicide: "Crop Protection",
  Herbicides: "Crop Protection",
  Fungicide: "Crop Protection",
  Fungicides: "Crop Protection",
  "PGR and Others": "Crop Nutrition",
};

// Returns the products to display for a gallery "view" (category or "Featured").
export function productsForView(view) {
  if (view === "Featured") {
    return products.filter((p) => p.isFeatured).slice(0, 8);
  }
  const category = VIEW_TO_CATEGORY[view] || view;
  return products.filter((p) => p.category === category);
}

export const formatINR = (value) =>
  `₹ ${Number(value).toLocaleString("en-IN")}.00`;
